/*! htmx.min.js placeholder – minimal polyfill for nut_webgui */
(function () {
  "use strict";

  // Auto-polling: hx-get + hx-trigger="every Xs" + hx-swap
  function setupPolling(el) {
    var trigger = el.getAttribute("hx-trigger") || "";
    var match = trigger.match(/every\s+(\d+)s/);
    if (!match) return;
    var interval = parseInt(match[1], 10) * 1000;
    var url = el.getAttribute("hx-get");
    if (!url) return;
    var swap = el.getAttribute("hx-swap") || "innerHTML";
    var select = el.getAttribute("hx-select");

    setInterval(function () {
      fetch(url, { headers: { "HX-Request": "true" } })
        .then(function (r) { return r.text(); })
        .then(function (html) {
          var tmp = document.createElement("div");
          tmp.innerHTML = html;
          var src = select ? tmp.querySelector(select) : tmp.firstElementChild;
          if (!src) return;
          if (swap === "outerHTML") {
            el.outerHTML = src.outerHTML;
          } else {
            el.innerHTML = src.innerHTML;
          }
        })
        .catch(function () {});
    }, interval);
  }

  // HTMX form submissions: hx-post, hx-patch
  function handleFormSubmit(el, e) {
    var method = (el.getAttribute("hx-post") ? "POST" :
                  el.getAttribute("hx-patch") ? "PATCH" : null);
    var url = el.getAttribute("hx-post") || el.getAttribute("hx-patch");
    if (!method || !url) return;

    var confirm = el.getAttribute("hx-confirm");
    if (confirm && !window.confirm(confirm)) {
      e.preventDefault();
      return;
    }

    e.preventDefault();

    var fd = new FormData(el);
    var body = {};
    fd.forEach(function (v, k) { body[k] = v; });

    fetch(url, {
      method: method,
      headers: { "Content-Type": "application/json", "HX-Request": "true" },
      body: JSON.stringify(body),
    })
      .then(function (r) {
        if (r.ok) {
          // Optional: show brief success indicator
          var btn = el.querySelector("button[type=submit]");
          if (btn) {
            var orig = btn.textContent;
            btn.textContent = "✓";
            setTimeout(function () { btn.textContent = orig; }, 1200);
          }
        } else {
          r.text().then(function (t) { alert("Error: " + t); });
        }
      })
      .catch(function (err) { alert("Request failed: " + err); });
  }

  document.addEventListener("DOMContentLoaded", function () {
    // Setup polling on elements with hx-get + hx-trigger
    document.querySelectorAll("[hx-get][hx-trigger]").forEach(setupPolling);

    // Intercept form submissions with hx-post or hx-patch
    document.addEventListener("submit", function (e) {
      var form = e.target;
      if (form.hasAttribute("hx-post") || form.hasAttribute("hx-patch")) {
        handleFormSubmit(form, e);
      }
    });
  });
})();
